+interface SessionToken {
+  sessionId: string;
+  userId: string;
+  issuedAt: number;
+  expiresAt: number;
+}
+
+// Initialize signing key from environment or generate for development
+const SIGNING_KEY = process.env.SESSION_SIGNING_KEY || randomBytes(32).toString("hex");
+
+export const createSessionToken = (sessionId: string, userId: string, expiresInSeconds: number = 3600): string => {
+  const now = Math.floor(Date.now() / 1000);
+  const payload: SessionToken = {
+    sessionId,
+    userId,
+    issuedAt: now,
+    expiresAt: now + expiresInSeconds,
+  };
+
+  const header = Buffer.from(JSON.stringify({ alg: "HS256", typ: "JWT" })).toString("base64url");
+  const body = Buffer.from(JSON.stringify(payload)).toString("base64url");
+  const signature = createHmac("sha256", SIGNING_KEY)
+    .update(`${header}.${body}`)
+    .digest("base64url");
+
+  return `${header}.${body}.${signature}`;
+};
+
+export const validateSessionToken = (token: string): SessionToken | null => {
+  try {
+    const parts = token.split(".");
+    if (parts.length !== 3) return null;
+
+    const [header, body, signature] = parts;
+    const expectedSignature = createHmac("sha256", SIGNING_KEY)
+      .update(`${header}.${body}`)
+      .digest("base64url");
+
+    if (signature !== expectedSignature) return null;
+
+    const payload = JSON.parse(Buffer.from(body, "base64url").toString()) as SessionToken;
+    const now = Math.floor(Date.now() / 1000);
+
+    if (payload.expiresAt < now) return null;
+
+    return payload;
+  } catch {
+    return null;
+  }
+};
